import type { MealsResponse } from "./types";
import { goalsOf, type Personalization } from "./nutrition";
import { mealCache, today } from "./mealCache";

export type MealPeriod = "Breakfast" | "Lunch" | "Dinner";

// Meals for `period`: today's saved result for this exact request if there is one
// (lib/mealCache.ts), otherwise generated by POST /api/meals and saved for next time.
export async function fetchMeals(userId: string, period: MealPeriod, p: Personalization, signal?: AbortSignal): Promise<MealsResponse> {
  const body = JSON.stringify({ period, restrictions: p.restrictions, goals: goalsOf(p), consumed: p.consumed });
  const day = today();
  const cached = await mealCache.get(userId, day, period, body).catch(() => null);
  if (cached) return cached;

  const res = await fetch("/api/meals", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body,
    signal,
  });
  if (!res.ok) {
    const error = await res.json().catch(() => ({}));
    throw new Error(error.error || `Server error ${res.status}`);
  }
  const meals: MealsResponse = await res.json();
  mealCache.put(userId, day, period, body, meals).catch(() => {}); // a failed save just means regenerating later
  return meals;
}
